int runSequence400(){juce::ScopedJuceInitialiser_GUI gui;auto require=[](bool ok,const char* what){if(!ok)throw std::runtime_error(what);};try{
 auto root=LibraryStore::root();root.createDirectory();SequenceClip clip;clip.bars=2;clip.key=3;clip.minor=true;clip.notes={{1,60,100,1,.13,.5},{2,63,73,1,2,1},{3,67,90,2,4,.25}};clip.nextId=4;auto file=root.getChildFile("Melody.mid");require(clip.save(file),"save MIDI");SequenceClip read;require(read.load(file)&&read.notes.size()==3&&read.key==3&&read.minor&&read.bars==2,"MIDI key/velocity/channels/length round trip");read.transpose(12);require(read.notes[0].pitch==72&&read.notes[1].pitch==75,"whole sequence transpose");require(read.save(file),"overwrite");SequenceClip overwritten;require(overwritten.load(file)&&overwritten.notes[0].pitch==72,"overwrite changes original");LibraryStore::update("tags.json",[&](auto& o){o.setProperty(file.getFullPathName(),"piano, melody");});require(LibraryStore::tagsFor(LibraryStore::read("tags.json"),file).contains("melody"),"MIDI tags");require(SequenceClip::fileKey(file)==3&&LibraryStore::typeFromValues(file,LibraryStore::read("playback-types.json"))==7,"MIDI browser key/type");
 require(std::abs(SequenceClip::snapped(.13+.25,.25,false)-.5)<1e-8&&SequenceClip::snapped(.38,.25,true)==.38,"absolute/free snap");
 Processor p(false);p.autoSave=false;p.sequence=clip;p.sequenceEnabled=true;p.prepareToPlay(48000,256);juce::MidiBuffer midi;midi.ensureSize(512*1024);double step=120./60/48000;
 p.renderSequenceMidi(midi,0,step,4096,true);int ons=0;for(auto e:midi)if(e.getMessage().isNoteOn()){++ons;require(std::abs(e.samplePosition-3120)<2,"sample accurate start");}require(ons==1,"one onset");
 midi.clear();p.renderSequenceMidi(midi,.2,step,128,true);ons=0;for(auto e:midi)if(e.getMessage().isNoteOn())++ons;require(ons==1,"seek into held note resumes");midi.clear();p.renderSequenceMidi(midi,.21,step,128,false);bool off=false;for(auto e:midi)off|=e.getMessage().isNoteOff();require(off,"transport stop releases sequence");
 // Loop boundaries fire once, and note-offs cross block boundaries.
 p.sequence.notes={{1,60,90,1,0,.5}};p.sequence.bars=1;++p.sequence.revision;p.sequenceWasPlaying=false;midi.clear();p.renderSequenceMidi(midi,3.999,step,128,true);ons=0;for(auto e:midi)if(e.getMessage().isNoteOn())++ons;require(ons==1,"exactly one wrap onset");midi.clear();p.renderSequenceMidi(midi,4.499,step,128,true);off=false;for(auto e:midi)off|=e.getMessage().isNoteOff();require(off,"wrap noteoff");
 p.oneShotMode=true;p.sequence.key=0;p.sequence.minor=true;p.masterSequenceKey->enabled=true;p.masterSequenceKey->key=5;p.masterSequenceKey->minor=false;require(p.sequencePitch(63)==69,"clip minor third maps to master major third");p.oneShotMode=false;require(p.sequencePitch(63)==63,"slice trigger identities unaffected by master key");
 p.sequence.notes.clear();p.sequenceRecord=true;midi.clear();midi.addEvent(juce::MidiMessage::noteOn(1,62,(juce::uint8)82),10);midi.addEvent(juce::MidiMessage::noteOff(1,62),110);p.captureSequenceMidi(midi,2,step,true);p.drainSequenceRecording();require(p.sequence.notes.size()==1&&p.sequence.notes[0].pitch==62&&p.sequence.notes[0].velocity==82&&std::abs(p.sequence.notes[0].length-100*step)<1e-8,"MIDI input record timing/velocity");
 p.sequence.notes.clear();midi.clear();midi.addEvent(juce::MidiMessage::noteOn(1,64,(juce::uint8)91),0);p.captureSequenceMidi(midi,3.99,step,true,256);midi.clear();midi.addEvent(juce::MidiMessage::noteOff(1,64),0);p.captureSequenceMidi(midi,0,step,true,256);p.drainSequenceRecording();require(p.sequence.notes.size()==1&&std::abs(p.sequence.notes[0].length-256*step)<1e-8,"record duration survives DAW loop wrap");
 juce::XmlElement xml("state");p.sequence.write(xml);SequenceClip restored;restored.read(xml.getChildByName("sequence"));require(restored.notes.size()==1&&restored.notes[0].pitch==64,"sequence project data");
 // Real playback through a one-shot voice, no GUI or independent transport required.
 auto data=std::make_shared<AudioData>();data->rate=48000;data->buffer.setSize(1,48000);for(int i=0;i<48000;++i)data->buffer.setSample(0,i,(float)(.2*std::sin(2*juce::MathConstants<double>::pi*220*i/48000)));data->path=root.getChildFile("Tone.wav").getFullPathName();require(writeRenderedAudio(juce::File(data->path),data->buffer,48000),"audio fixture");p.audio=data;p.oneShotMode=true;p.shotRootNote=60;p.shotEnd=48000;p.shotVelocity=100;p.shotEnvelope={.005f,.1f,.8f,.05f};p.masterSequenceKey->enabled=false;p.sequenceRecord=false;p.sequence.notes={{1,60,100,1,0,.1}};p.sequence.bars=1;++p.sequence.revision;
 struct Head:juce::AudioPlayHead{double beat=0;bool playing=true;juce::Optional<PositionInfo> getPosition()const override{PositionInfo p;p.setPpqPosition(beat);p.setBpm(120);p.setIsPlaying(playing);return p;}} head;p.setPlayHead(&head);juce::AudioBuffer<float> audio(2,256);midi.clear();p.processBlock(audio,midi);require(audio.getMagnitude(0,256)>.001,"sequence drives actual instrument");head.playing=false;head.beat+=256*step;for(int i=0;i<30;++i){p.processBlock(audio,midi);head.beat+=256*step;}require(audio.getMagnitude(0,256)<1e-6,"stopped sequence releases audio");
 SequencerEditor panel(p);panel.setSize(900,450);require(panel.gesturesForCheck(),"native mouse gestures");auto png=root.getChildFile("sequence400.png").createOutputStream();juce::PNGImageFormat fmt;if(png)fmt.writeImageToStream(panel.createComponentSnapshot(panel.getLocalBounds()),*png);
 // Browser selection keeps the sample/instrument, and opens the editor immediately.
 {p.split(1,false);Editor editor(p);editor.diagnosticQuietAnalysis();editor.setSize(1360,1000);require(editor.sequenceBrowserForCheck(file),"MIDI browser loads without replacing sample");auto stream=root.getChildFile("sequence-editor400.png").createOutputStream();if(stream)fmt.writeImageToStream(editor.createComponentSnapshot(editor.getLocalBounds()),*stream);}
 auto compact=root.getChildFile("sequence-compact400.png").createOutputStream();panel.setSize(620,390);if(compact)fmt.writeImageToStream(panel.createComponentSnapshot(panel.getLocalBounds()),*compact);
 RackProcessor rack;rack.masterSequenceKey->enabled=true;rack.masterSequenceKey->key=7;rack.loops[0]->sequence=clip;rack.loops[0]->sequenceEnabled=true;auto rackState=rack.stateXml();require(rack.loops[0]->masterSequenceKey==rack.loops[7]->masterSequenceKey&&rackState->getIntAttribute("masterKey")==7,"shared master key");RackProcessor rackRestored;require(rackRestored.restore(*rackState,true)&&rackRestored.masterSequenceKey->enabled&&rackRestored.masterSequenceKey->key==7&&rackRestored.loops[0]->sequence.notes.size()==3&&rackRestored.loops[0]->sequenceEnabled,"rack restores master and sequence without loaded audio");
 auto started=juce::Time::getMillisecondCounterHiRes();for(int i=0;i<100;++i){SequenceClip c;require(c.load(file),"load benchmark");}std::cout<<"MIDI load average "<<(juce::Time::getMillisecondCounterHiRes()-started)/100<<" ms\n";std::cout<<"Sequencer MIDI round trip, absolute snap, transport, recording, scales, native gestures, browser and actual playback passed.\n";return 0;
 }catch(const std::exception& e){std::cerr<<"Sequence FAIL: "<<e.what()<<"\n";return 4001;}}
